# In Django < 5.0, Script class is not available and needed for the test case.
# It's a simple wrapper for a JS path with attributes.
# Since we can't import it from Django, we define a minimal version.
class Script:
    def __init__(self, path, attrs=None):
        self.path = path
        self.attrs = attrs or {}

    def __repr__(self):
        return f'Script("{self.path}")'

    def __eq__(self, other):
        return isinstance(other, Script) and self.path == other.path and self.attrs == other.attrs

    def __hash__(self):
        # A simple hash based on path for deduplication purposes
        return hash(self.path)


def get_js_paths(media_obj):
