import collections

class SafeString(str):
    def __html__(self):
        return self

def mark_safe(s):
    return SafeString(s)

# Minimal reimplementation of Django's Media class to demonstrate the issue.
class Media:
    def __init__(self, css=None, js=None):
        self._css = css or {}
        self._js = js or []

    def __str__(self):
        return self.render()

    def render(self):
        js_output = "\n".join(self.render_js())
        return js_output

    def _get_js(self):
        # This logic is equivalent to using Django's OrderedSet or dict.fromkeys
        # for deduplication. It relies on object equality.
        seen = set()
        output = []
        for path in self._js:
            if path not in seen:
                output.append(path)
                seen.add(path)
        return output

    def render_js(self):
        for path in self._get_js():
            if hasattr(path, "__html__"):
                yield str(path)
            else:
                # Simplified rendering for a plain path string
                yield f'<script src="{path}"></script>'

js_path = "/path/to/asset.js"
js_tag = mark_safe('<script src="/path/to/asset.js"></script>')

# Media object containing two references to the same script:
# one as a path, one as a pre-rendered, safe HTML tag.
media = Media(js=[js_path, js_tag])

output = str(media)

# The deduplication logic fails because it treats the path and the tag as
# different items, resulting in two script tags for the same asset.
expected_duplicated_output = (
    '<script src="/path/to/asset.js"></script>\n'
    '<script src="/path/to/asset.js"></script>'
)

if output == expected_duplicated_output:
    print("CONFIRMED")
else:
    print("REFUTED")

