    MAX_FRAME_SIZE = 5

def demonstrate_wrong_order_of_operations():
    conn = MockH2Connection()
    crawler_settings = MockCrawlerSettings()

    # The following block simulates the logic in the connectionMade function.

    # 1. Initiate connection (queues first SETTINGS frame)
    conn.initiate_connection()

    # 2. Get custom setting
    max_frame_size = crawler_settings.getint("HTTP2_MAX_FRAME_SIZE")

    # 3. Check if custom setting differs from default and update if so
    if max_frame_size != conn.local_settings.max_frame_size:
        # This queues a second SETTINGS frame
        conn.update_settings({MockSettingCodes.MAX_FRAME_SIZE: max_frame_size})

    # The flaw is that two methods that queue SETTINGS frames are called in succession.
    # The correct approach is to configure the setting *before* initiating the connection,
    # so that the first SETTINGS frame contains the correct value.
    if conn.call_log == ["initiate_connection", "update_settings"]:
        print("CONFIRMED")
    else:
        print("REFUTED")

