class MockItem:
    def __init__(self, markers):
        # Store markers as they would be during pytest collection
        self.own_markers = list(markers)

    def get_closest_marker(self, name):
        # pytest-rerunfailures uses get_closest_marker, which respects scope.
        # For markers on the same node (the item), it returns the last one added.
        for marker in reversed(self.own_markers):
            if marker.name == name:
                return marker
        return None

    def add_marker(self, marker):
        # pytest's add_marker appends to the list of markers on the item.
        self.own_markers.append(marker)


