import unittest.mock

class App:
    def __init__(self):
        class Conf:
            pass
        self.conf = Conf()
        self.conf.result_cache_max = -1

class RPCBackend:
    def __init__(self, app):
        self.app = app
        self.instance_id = id(self)

class TestLifecycle:
    def __init__(self):
        self.app = App()
        self.setup_method()

    def setup_method(self):
        self.b = RPCBackend(app=self.app)

    def slurp(self, messages):
        # This helper uses self.b
        return self.b.instance_id

    def test_something_with_self_b(self):
        # This test uses self.b via slurp
        slurped_id = self.slurp([])
        return self.b.instance_id == slurped_id

    def test_final_state_cached_when_cache_enabled(self):
        # This test modifies config and creates a local backend 'b',
        # which is different from self.b.
        old_cache_max = self.app.conf.result_cache_max
        self.app.conf.result_cache_max = 100
        try:
            b = RPCBackend(app=self.app)
            # Any helper call like self.slurp() would act on self.b, not the local b.
            slurped_id = self.slurp([]) 
            return b.instance_id != slurped_id
